<template><view class="withdraw-detail-page"><jk-page-nav title="提现详情"/><view v-if="detail" class="detail-content"><view class="status-card"><jk-icon :name="statusIcon" size="xl"/><text class="amount">¥{{money(detail.amount)}}</text><jk-status-tag :text="detail.withdrawStatusText||detail.statusText||withdrawStatusText(detail.status)" :tone="statusTone"/><small>{{statusDesc}}</small></view><view class="card"><view class="row"><text>提现单号</text><strong>{{detail.withdrawNo||'-'}}</strong></view><view class="row"><text>申请人</text><strong>{{detail.applicantName||'用户不存在'}}</strong></view><view class="row"><text>身份</text><strong>{{detail.roleName||'身份未配置'}}</strong></view><view class="row"><text>申请时间</text><strong>{{formatTime(detail.createTime)}}</strong></view><view class="row"><text>收款信息</text><strong>{{payeeText}}</strong></view><view v-if="detail.rejectReason" class="row danger"><text>驳回原因</text><strong>{{detail.rejectReason}}</strong></view></view></view></view></template>
<script>import JkPageNav from'@/components/jk/jk-page-nav.vue';import JkIcon from'@/components/jk/jk-icon.vue';import JkStatusTag from'@/components/jk/jk-status-tag.vue';import{getJkWithdrawDetail}from'@/api/jk.js';import{jkWithdrawStatusText}from'@/utils/jk-display.js';export default{components:{JkPageNav,JkIcon,JkStatusTag},data(){return{detail:null}},computed:{normalized(){const t=String((this.detail||{}).status||'').toUpperCase();if(t.includes('REJECT'))return'rejected';if(t.includes('PAID')||t.includes('SUCCESS')||t.includes('CONFIRM'))return'paid';return'processing'},statusTone(){return this.normalized==='paid'?'success':this.normalized==='rejected'?'danger':'info'},statusIcon(){return this.normalized==='paid'?'success':this.normalized==='rejected'?'error':'clock'},statusDesc(){return this.normalized==='paid'?'提现已成功到账':this.normalized==='rejected'?'提现申请未通过':'提现申请正在处理中'},payeeText(){try{const d=typeof this.detail.payeeSnapshotJson==='string'?JSON.parse(this.detail.payeeSnapshotJson):this.detail.payeeSnapshotJson||{};return[d.bankName,d.account].filter(Boolean).join(' ')||'-'}catch(e){return this.detail.payeeSnapshotJson||'-'}}},onLoad(q){getJkWithdrawDetail(q.id).then(r=>this.detail=r.data||r||{})},methods:{withdrawStatusText(v){return jkWithdrawStatusText(v)},money(v){const n=Number(v||0);return Number.isNaN(n)?String(v||'0.00'):n.toFixed(2)},formatTime(v){return v?String(v).replace('T',' ').slice(0,19):'-'}}};</script>
<style scoped>.withdraw-detail-page{min-height:100vh;background:#f7f9f9}.detail-content{padding:18rpx 22rpx 36rpx}.status-card{display:flex;flex-direction:column;align-items:center;padding:32rpx;border-radius:20rpx;background:linear-gradient(135deg,#eafaf6,#fff)}.amount{margin:12rpx 0;color:#263139;font-size:40rpx;font-weight:700}.status-card small{margin-top:10rpx;color:#7e8a90;font-size:21rpx}.card{margin-top:18rpx;padding:22rpx;border-radius:20rpx;background:#fff}.row{display:flex;align-items:flex-start;justify-content:space-between;gap:20rpx;min-height:74rpx;padding:10rpx 0;border-bottom:1rpx solid #edf1f0}.row:last-child{border-bottom:0}.row text{color:#77848a;font-size:23rpx}.row strong{max-width:430rpx;color:#273239;text-align:right;font-size:23rpx;font-weight:500;line-height:1.5}.row.danger strong{color:#ef5b4c}</style>
